using System;
using System.Collections.Generic;
using System.Linq;

public class Inventory
{
    private readonly Dictionary<string, int> items = new();
    private readonly int maxSlots;

    public Inventory(int maxSlots) { this.maxSlots = maxSlots; }

    public int SlotsUsed => items.Count;

    public bool Add(string item, int count)
    {
        if (count < 1) throw new ArgumentOutOfRangeException(nameof(count));
        string key = item.Trim().ToLowerInvariant();
        if (!items.ContainsKey(key) && items.Count >= maxSlots) return false;
        items[key] = items.GetValueOrDefault(key) + count;
        return true;
    }

    public int Take(string item, int count)
    {
        string key = item.Trim().ToLowerInvariant();
        int have = items.GetValueOrDefault(key);
        int t = Math.Min(have, count);
        if (have - t <= 0) items.Remove(key); else items[key] = have - t;
        return t;
    }

    public int CountOf(string item) => items.GetValueOrDefault(item.Trim().ToLowerInvariant());

    public override string ToString() => items.Count == 0 ? "(empty)" : string.Join(", ", items.OrderBy(kv => kv.Key).Select(kv => $"{kv.Key} x{kv.Value}"));
}
